from __future__ import annotations
import csv, json, statistics
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OLD=ROOT/'results/v3_1/P1_02_YELLOW_ENET_20261016'
NEW=ROOT/'results/v3_1/P1_02_YELLOW_SPARSE_ENET_20261016'
OUT=ROOT/'results/v3_1/P1_02_YELLOW_SPARSE_ENET_20261016/YELLOW_FIXED21_VS_SPARSE4_COMPARISON.json'

def tsv(path):
    with path.open(newline='') as h: return list(csv.DictReader(h,delimiter='\t'))
old=json.loads((OLD/'YELLOW_ENET_NESTED_SUMMARY.json').read_text())
new=json.loads((NEW/'YELLOW_SPARSE_NESTED_SUMMARY.json').read_text())
old_meta=tsv(OLD/'YELLOW_ENET_NESTED_TASK_METADATA.tsv');new_meta=tsv(NEW/'YELLOW_SPARSE_NESTED_TASK_METADATA.tsv')
old_full=[r['gene_symbol'] for r in tsv(OLD/'YELLOW_ENET_FULL_COEFFICIENTS.tsv')]
new_full=[r['gene_symbol'] for r in tsv(NEW/'YELLOW_SPARSE_FULL_COEFFICIENTS.tsv')]
old_freq={r['gene_symbol']:float(r['selection_frequency']) for r in tsv(OLD/'YELLOW_ENET_NESTED_SELECTION_FREQUENCY.tsv')}
new_freq={r['gene_symbol']:float(r['selection_frequency']) for r in tsv(NEW/'YELLOW_SPARSE_NESTED_SELECTION_FREQUENCY.tsv')}
old_rep={r['repeat_id']:float(r['heldout_harrell_c']) for r in tsv(OLD/'YELLOW_ENET_NESTED_REPEAT_CONCORDANCE.tsv')}
new_rep={r['repeat_id']:float(r['heldout_harrell_c']) for r in tsv(NEW/'YELLOW_SPARSE_NESTED_REPEAT_CONCORDANCE.tsv')}
assert set(old_rep)==set(new_rep) and len(old_rep)==20
paired=[new_rep[k]-old_rep[k] for k in sorted(old_rep)]
of=[old_freq[g] for g in old_full];nf=[new_freq[g] for g in new_full]
ons=[int(float(r['selected_n'])) for r in old_meta];nns=[int(float(r['selected_n'])) for r in new_meta]
report={
 'schema':'V31_YELLOW_FIXED21_VS_SPARSE4_DESCRIPTIVE_COMPARISON_V1',
 'status':'COMPUTED_PENDING_DIFFERENT_ROLE_INDEPENDENT_AUDIT',
 'shared_contract':{'candidate_n':492,'patients':476,'events':220,'outer_repeats':20,'outer_folds':5,'bootstrap':False},
 'fixed_alpha_21_gene':{
   'full_selected_n':len(old_full),'full_selected_genes':old_full,
   'nested_patient_mean_harrell_c':old['patient_mean_heldout_harrell_c'],
   'nested_repeat_mean_harrell_c':old['repeat_mean_harrell_c'],
   'nested_repeat_sd_harrell_c':old['repeat_sd_harrell_c'],
   'outer_selected_n_median':statistics.median(ons),'outer_selected_n_min':min(ons),'outer_selected_n_max':max(ons),
   'full_gene_outer_frequency_median':statistics.median(of),'full_gene_outer_frequency_min':min(of),'full_gene_outer_frequency_max':max(of),
   'full_gene_frequency_below_0_5_n':sum(x<.5 for x in of),'full_external_coverage_cohort_n':0},
 'sparse_4_gene':{
   'full_selected_n':len(new_full),'full_selected_genes':new_full,
   'nested_patient_mean_harrell_c':new['patient_mean_heldout_harrell_c'],
   'nested_repeat_mean_harrell_c':new['repeat_mean_harrell_c'],
   'nested_repeat_sd_harrell_c':new['repeat_sd_harrell_c'],
   'outer_selected_n_median':statistics.median(nns),'outer_selected_n_min':min(nns),'outer_selected_n_max':max(nns),
   'full_gene_outer_frequency_median':statistics.median(nf),'full_gene_outer_frequency_min':min(nf),'full_gene_outer_frequency_max':max(nf),
   'full_gene_frequency_below_0_5_n':sum(x<.5 for x in nf),'full_external_coverage_cohort_n':2},
 'sparse_minus_fixed':{
   'nested_patient_mean_harrell_c':new['patient_mean_heldout_harrell_c']-old['patient_mean_heldout_harrell_c'],
   'nested_repeat_mean_harrell_c':new['repeat_mean_harrell_c']-old['repeat_mean_harrell_c'],
   'nested_repeat_sd_ratio':new['repeat_sd_harrell_c']/old['repeat_sd_harrell_c'],
   'paired_repeat_delta_median':statistics.median(paired),'paired_repeat_delta_min':min(paired),'paired_repeat_delta_max':max(paired),
   'paired_repeats_sparse_higher_n':sum(x>0 for x in paired)},
 'interpretation':{
   'parsimony':'SPARSE4_STRONGLY_BETTER',
   'full_model_gene_selection_stability':'SPARSE4_BETTER_DESCRIPTIVELY',
   'conditional_internal_discrimination':'NEAR_EQUIVALENT_WITH_SMALL_NUMERICAL_DECREMENT_FOR_SPARSE4',
   'external_transportability':'SPARSE4_BETTER_TWO_FULL_COHORTS_VS_ZERO',
   'external_performance':'HETEROGENEOUS_AND_NOT_BH_ROBUST',
   'overall':'MORE_PARSIMONIOUS_AND_TRANSPORTABLE_WITH_A_STABLE_CORE_BUT_NOT_HIGHER_INTERNAL_OR_EXTERNAL_DISCRIMINATION'},
 'claim_boundary':'DESCRIPTIVE_SAME_SPLIT_COMPARISON; REPEATED_CV_ESTIMATES_ARE_DEPENDENT AND NO INDEPENDENCE-BASED P VALUE IS REPORTED'
}
tmp=OUT.with_name(OUT.name+'.tmp');tmp.write_text(json.dumps(report,indent=2,sort_keys=True)+'\n');tmp.replace(OUT)
print(json.dumps(report['interpretation'],indent=2))
